// Sub2APIManagerServer is the server API for Sub2APIManager service.
// All implementations must embed UnimplementedSub2APIManagerServer
// for forward compatibility.
//
// Sub2API 公共首页与管理
type Sub2APIManagerServer interface {
	// 获取 Sub2API 公开首页数据（无需鉴权）
	PublicSub2APIHome(context.Context, *PublicSub2APIHomeRequest) (*PublicSub2APIHomeResponse, error)
	// 获取 Sub2API 配置
	GetSub2APIConfig(context.Context, *GetSub2APIConfigRequest) (*GetSub2APIConfigResponse, error)
	// 更新 Sub2API 配置
	UpdateSub2APIConfig(context.Context, *UpdateSub2APIConfigRequest) (*UpdateSub2APIConfigResponse, error)
	// 测试 Sub2API 管理员连接
	TestSub2APIConnection(context.Context, *TestSub2APIConnectionRequest) (*TestSub2APIConnectionResponse, error)
	// 手动同步 Sub2API 使用记录
	SyncSub2APIUsage(context.Context, *SyncSub2APIUsageRequest) (*SyncSub2APIUsageResponse, error)
	// 获取 Sub2API 当前聚合快照
	GetSub2APISnapshot(context.Context, *GetSub2APISnapshotRequest) (*GetSub2APISnapshotResponse, error)
	// 获取指定时间区间的公开用量统计（无需鉴权）
	GetPublicSub2APIStats(context.Context, *GetSub2APIStatsRequest) (*GetSub2APIStatsResponse, error)
	// 管理端用量汇总（标量指标 + 区间标签，需鉴权）
	GetSub2APIAdminTotals(context.Context, *GetSub2APIAdminTotalsRequest) (*GetSub2APIAdminTotalsResponse, error)
	// 管理端用量趋势（按区间跨度日内分桶/按天，需鉴权）
	GetSub2APIAdminTrend(context.Context, *GetSub2APIAdminTrendRequest) (*GetSub2APIAdminTrendResponse, error)
	// 管理端用量排行（模型 + 分组，按 token 降序，需鉴权）
	GetSub2APIAdminTop(context.Context, *GetSub2APIAdminTopRequest) (*GetSub2APIAdminTopResponse, error)
	// 获取管理端最近请求（按时间区间分页，需鉴权）
	GetSub2APIRecentRequests(context.Context, *GetSub2APIRecentRequestsRequest) (*GetSub2APIRecentRequestsResponse, error)
	// 公告管理
	ListSub2APIAnnouncements(context.Context, *ListSub2APIAnnouncementsRequest) (*ListSub2APIAnnouncementsResponse, error)
	CreateSub2APIAnnouncement(context.Context, *CreateSub2APIAnnouncementRequest) (*Sub2APIAnnouncementResponse, error)
	UpdateSub2APIAnnouncement(context.Context, *UpdateSub2APIAnnouncementRequest) (*Sub2APIAnnouncementResponse, error)
	DeleteSub2APIAnnouncement(context.Context, *DeleteSub2APIAnnouncementRequest) (*DeleteSub2APIAnnouncementResponse, error)
	// 时间线管理
	ListSub2APITimeline(context.Context, *ListSub2APITimelineRequest) (*ListSub2APITimelineResponse, error)
	CreateSub2APITimelineItem(context.Context, *CreateSub2APITimelineItemRequest) (*Sub2APITimelineItemResponse, error)
	UpdateSub2APITimelineItem(context.Context, *UpdateSub2APITimelineItemRequest) (*Sub2APITimelineItemResponse, error)
	DeleteSub2APITimelineItem(context.Context, *DeleteSub2APITimelineItemRequest) (*DeleteSub2APITimelineItemResponse, error)
	// ---------- 每日抽奖活动（管理端，需鉴权） ----------
	// 三段概览（累计中 / 报名中 / 配置）
	GetLotteryOverview(context.Context, *GetLotteryOverviewRequest) (*GetLotteryOverviewResponse, error)
	// 更新抽奖配置
	UpdateLotterySettings(context.Context, *UpdateLotterySettingsRequest) (*UpdateLotterySettingsResponse, error)
	// 历史轮次分页
	ListLotteryRounds(context.Context, *ListLotteryRoundsRequest) (*ListLotteryRoundsResponse, error)
	// 某轮次详情（含中奖名单）
	GetLotteryRoundDetail(context.Context, *GetLotteryRoundDetailRequest) (*GetLotteryRoundDetailResponse, error)
	// 某轮次报名者名单（仅本地快照：用户id/用户名/消费额）
	ListLotteryRegistrants(context.Context, *ListLotteryRegistrantsRequest) (*ListLotteryRegistrantsResponse, error)
	// 单个 Sub2API 用户详情（点击报名者时实时拉取）
	GetSub2APIUser(context.Context, *GetSub2APIUserRequest) (*GetSub2APIUserResponse, error)
	// 手动发放某轮次奖金（autoPayout 关或重试失败时）
	DistributeLotteryRound(context.Context, *DistributeLotteryRoundRequest) (*DistributeLotteryRoundResponse, error)
	// 手动立即结算（测试/补偿）
	TriggerLotterySettle(context.Context, *TriggerLotterySettleRequest) (*TriggerLotterySettleResponse, error)
	// 手动立即开奖（测试/补偿）
	TriggerLotteryDraw(context.Context, *TriggerLotteryDrawRequest) (*TriggerLotteryDrawResponse, error)
	// ---------- 每日抽奖活动（用户端，内嵌 sub2api，X-Sub2API-Token 鉴权） ----------
	// 用户端状态（累计奖池 + 倒计时 + 报名中轮次 + 本人资格/是否已报名）
	GetLotteryStatus(context.Context, *GetLotteryStatusRequest) (*GetLotteryStatusResponse, error)
	// 报名当前轮次
	RegisterLottery(context.Context, *RegisterLotteryRequest) (*RegisterLotteryResponse, error)
	// 用户端历史 + 本人参与情况
	ListLotteryHistoryPublic(context.Context, *ListLotteryHistoryPublicRequest) (*ListLotteryHistoryPublicResponse, error)
	mustEmbedUnimplementedSub2APIManagerServer()
}

